return (async () => {
// The two examples the reference shows open (previews 4 and 5, "Sides" and "Skip transition"): every
// card pinned open, the pointer ignored so a stray hover cannot close one mid-read.
//
// Each group is scrolled so its triggers sit where the REFERENCE's do, then opened. Placement flips to
// whichever side has room, measured against the viewport at the moment the card opens, and that is
// correct behaviour. Two things follow from it:
//   - A group still below the fold measures a trigger at y≈1100 in a 924-tall window, so every card
//     flips to `top` whatever it asked for, and the reference's four sides collapse to one.
//   - Our docs page is taller than the mirror, so the same example sits lower. The reference measures
//     these triggers at y≈637 with no scrolling and resolves top, bottom, left and right. Putting ours
//     at the same offset reproduces that, instead of `bottom` and `right` flipping for want of room.
const REFERENCE_TRIGGER_Y = 637;
const previews = [...document.querySelectorAll(".showcase .preview")];
const settle = () => new Promise((r) => setTimeout(r, 150));
for (const preview of previews.slice(3)) {
  const els = [...preview.querySelectorAll("acme-context-card")];
  if (!els.length) continue;
  const top = els[0].getBoundingClientRect().top + window.scrollY;
  window.scrollTo({ top: Math.max(0, top - REFERENCE_TRIGGER_Y), behavior: "instant" });
  await settle();
  for (const el of els) { el.disableTriggers = true; el.shown = 1; }
  await Promise.all(els.map((el) => el.updateComplete));
  await settle();
}
})();
